function moduleSummaryCards(page){
 const rows=state.records||[],today=epiToday(),peopleCount=list=>new Set(list.map(r=>String(r.matricula||r.funcionario||"").trim().toUpperCase()).filter(Boolean)).size;
 const card=(label,value,sub="")=>`<article class="stat-card"><span>${label}</span><b>${value}</b>${sub?`<small>${sub}</small>`:""}</article>`;
 if(page==="demissions"){
  const planned=rows.filter(r=>r.data_fim_aviso&&r.data_fim_aviso>=today).length;
  return `<div class="stats-grid module-summary">${card("DEMISSÕES PROGRAMADAS",peopleCount(rows.filter(r=>r.data_fim_aviso&&r.data_fim_aviso>=today)),"Avisos com término previsto hoje ou futuramente")}</div>`;
 }
 if(page==="leave"){
  const current=rows.filter(r=>r.inicio_gozo&&r.fim_gozo&&r.inicio_gozo<=today&&r.fim_gozo>=today).length;
  const planned=rows.filter(r=>r.inicio_gozo&&r.inicio_gozo>today).length;
  return `<div class="stats-grid module-summary">${card("FUNCIONÁRIOS DE FÉRIAS",peopleCount(rows.filter(r=>r.inicio_gozo&&r.fim_gozo&&r.inicio_gozo<=today&&r.fim_gozo>=today)))}${card("FÉRIAS PROGRAMADAS",peopleCount(rows.filter(r=>r.inicio_gozo&&r.inicio_gozo>today)))}</div>`;
 }
 if(page==="medical"){
  const active=rows.filter(r=>{const start=r.data_ocorrido,end=r.data_termino||(r.data_retorno?addDays(r.data_retorno,-1):(Number(r.dias_afastamento)>0?addDays(start,Number(r.dias_afastamento)-1):null));return start&&start<=today&&end&&end>=today}).length;
  const inss=rows.filter(r=>{const start=r.data_ocorrido,end=r.data_termino||(r.data_retorno?addDays(r.data_retorno,-1):(Number(r.dias_afastamento)>0?addDays(start,Number(r.dias_afastamento)-1):null));return (String(r.tipo||"").toUpperCase()==="ATESTADO INSS"||String(r.afastamento||"").toUpperCase()==="SIM")&&start&&start<=today&&end&&end>=today}).length;
  return `<div class="stats-grid module-summary">${card("FUNCIONÁRIOS AFASTADOS",peopleCount(rows.filter(r=>{const start=r.data_ocorrido,end=r.data_termino||(r.data_retorno?addDays(r.data_retorno,-1):(Number(r.dias_afastamento)>0?addDays(start,Number(r.dias_afastamento)-1):null));return start&&start<=today&&end&&end>=today})))}${card("AFASTADOS INSS",peopleCount(rows.filter(r=>{const start=r.data_ocorrido,end=r.data_termino||(r.data_retorno?addDays(r.data_retorno,-1):(Number(r.dias_afastamento)>0?addDays(start,Number(r.dias_afastamento)-1):null));return (String(r.tipo||"").toUpperCase()==="ATESTADO INSS"||String(r.afastamento||"").toUpperCase()==="SIM")&&start&&start<=today&&end&&end>=today})))}</div>`;
 }
 return "";
}

function attachFixedHorizontalScroll(){
 const tableWrap=document.querySelector("#pageContent .table-wrap");if(!tableWrap)return;
 document.querySelector("#fixedXScroll")?.remove();
 const bar=document.createElement("div");bar.id="fixedXScroll";bar.innerHTML='<div></div>';document.body.appendChild(bar);
 const inner=bar.firstElementChild;
 const syncSize=()=>{inner.style.width=tableWrap.scrollWidth+"px";bar.style.display=tableWrap.scrollWidth>tableWrap.clientWidth?"block":"none"};
 let lock=false;
 bar.addEventListener("scroll",()=>{if(lock)return;lock=true;tableWrap.scrollLeft=bar.scrollLeft;lock=false});
 tableWrap.addEventListener("scroll",()=>{if(lock)return;lock=true;bar.scrollLeft=tableWrap.scrollLeft;lock=false});
 syncSize();window.addEventListener("resize",syncSize,{once:true});
}
