 if(db&&profList){const r=await db.from("lancamentos_medicos").select("profissional,crm_cro");const rows=r.data||[];const known=[...new Map(rows.filter(x=>x.profissional&&x.crm_cro).map(x=>[x.profissional.toLocaleUpperCase(),{nome:x.profissional,crm:x.crm_cro}])).values()];profList.innerHTML=known.map(v=>`<option value="${escapeHTML(v.nome)}"></option>`).join("");const crmList=$("#crmLista");if(crmList)crmList.innerHTML=known.map(v=>`<option value="${escapeHTML(v.crm)}" label="${escapeHTML(v.nome)}"></option>`).join("");const fillProf=()=>{const v=known.find(x=>String(x.crm).replace(/[^A-Za-z0-9]/g,"").toUpperCase()===String(crm?.value||"").replace(/[^A-Za-z0-9]/g,"").toUpperCase()&&String(crm?.value||"").trim()!=="");if(v&&profissional)profissional.value=v.nome};["input","change","blur"].forEach(ev=>crm?.addEventListener(ev,fillProf));const fillCrm=()=>{const v=known.find(x=>x.nome.toLocaleUpperCase()===String(profissional?.value||"").trim().toLocaleUpperCase());if(v&&crm)crm.value=v.crm;};profissional?.addEventListener("change",fillCrm);profissional?.addEventListener("blur",fillCrm);}
