 rows.forEach(r=>{const months=validity.get(String(r.tipo||"").trim().toLocaleUpperCase("pt-BR"))||Number(r.tempo_validade)||0;if(months>0){r.tempo_validade=months;r.validade=addMonths(r.data_entrega,months)}});
